code:
static MemoryPrompt build(MemoryPrompt source, int maxTurns, int maxMessages,
                              long maxTokens, AgentContextTokenEstimator tokenEstimator,
                              boolean compactCompletedToolTurns, int keepRecentTurns,
                              AgentContextCompressor contextCompressor,
                              AgentCompressionFailureStrategy compressionFailureStrategy) {
        // 这些限制只作用于模型视图；Turn/ChatMemory 中的完整历史仍由业务层保留。
        if (source == null) throw new IllegalArgumentException("source prompt must not be null");
        if (maxTurns <= 0 || maxMessages <= 0 || maxTokens < 0) {
            throw new IllegalArgumentException("context limits must be positive, maxTokens may be zero");
        }
        // 多取一轮用于识别边界；最终发送窗口仍严格限制为 maxTurns。
        List<Message> history = readHistory(source.getMemory(), maxTurns);
        List<List<Message>> turns = splitTurns(history);
        int from = Math.max(0, turns.size() - maxTurns);
        // 当前 Turn 永远不能被压缩；即使配置为 0，也至少保护当前这一轮。
        int compressionEnd = Math.max(from, turns.size() - Math.max(1, keepRecentTurns));
        List<Message> semanticInput = new ArrayList<>();
        boolean allCompressible = true;
        // 语义压缩只接收较早、已完成的 Turn；挂起或失败的协议消息不能交给摘要器猜测。
        for (int index = from; index < compressionEnd; index++) {
            List<Message> turn = turns.get(index);
            // compactCompletedToolTurns 是独立的压缩策略；配置语义压缩器时，先将较早工具 Turn
            // 压缩为 UserMessage + 最终 AiMessage，再把结果交给语义压缩器。
            semanticInput.addAll(compactCompletedToolTurns ? compact(turn) : copy(turn));
            allCompressible &= isCompletedTurn(turn);
        }
        List<Message> semanticOutput = null;
        if (contextCompressor != null && allCompressible && !semanticInput.isEmpty()) {
            // 传入不可修改副本，防止业务压缩器意外修改 Runner 正在使用的历史对象。
            try {
                semanticOutput = contextCompressor.compress(Collections.unmodifiableList(copy(semanticInput)));
                AgentContextCompressionValidator.validate(semanticOutput, true);
            } catch (RuntimeException error) {
                if (compressionFailureStrategy == AgentCompressionFailureStrategy.FAIL) throw error;
                semanticOutput = null;
            }
        }
        // 每个元素都是不可拆分的历史单元：语义压缩结果、一个旧 Turn 或一个受保护 Turn。
        // 超过消息上限时只删除最早单元，永远不会从 ToolCall/ToolMessage 中间截断。
        List<List<Message>> units = new ArrayList<>();
        if (semanticOutput != null) {
            units.add(copy(semanticOutput));
        }
        for (int index = compressionEnd; index < turns.size(); index++) {
            units.add(copy(turns.get(index)));
        }
        if (semanticOutput == null) {
            units.clear();
            for (int index = from; index < compressionEnd; index++) {
                List<Message> turn = turns.get(index);
                boolean current = index == turns.size() - 1;
                units.add(compactCompletedToolTurns && !current ? compact(turn) : copy(turn));
            }
            for (int index = compressionEnd; index < turns.size(); index++) {
                units.add(copy(turns.get(index)));
            }
        }
        int firstUnit = 0;
        int size = countMessages(units);
        // Drop the oldest complete units until the message budget is met. The
        // newest unit is always retained so the current turn cannot disappear.
        while (size > maxMessages && firstUnit < units.size() - 1) {
            size -= units.get(firstUnit++).size();
        }
        List<Message> selected = new ArrayList<>();
        for (int index = firstUnit; index < units.size(); index++) selected.addAll(units.get(index));
        if (maxTokens > 0 && tokenEstimator != null) {
            long estimatedTokens = tokenEstimator.estimate(selected);
            if (estimatedTokens < 0) {
                throw new IllegalArgumentException("contextTokenEstimator must return a non-negative value");
            }
            while (selected.size() > 1 && estimatedTokens > maxTokens
                && firstUnit < units.size() - 1) {
                selected.subList(0, units.get(firstUnit++).size()).clear();
                estimatedTokens = tokenEstimator.estimate(selected);
                if (estimatedTokens < 0) {
                    throw new IllegalArgumentException("contextTokenEstimator must return a non-negative value");
                }
            }
        }

        // 只复制 Prompt 的配置和模型可见消息；temporaryMessages 仍作为 UI/运行时消息单独复制。
        MemoryPrompt result = new MemoryPrompt();
        result.setMetadataMap(source.getMetadataMap());
        result.setSystemMessage(source.getSystemMessage() == null
            ? null : source.getSystemMessage().copy());
        result.setTools(source.getTools());
        result.setToolGroups(source.getToolGroups());
        result.setChatInterceptorProviders(source.getChatInterceptorProviders());
        result.setToolChoice(source.getToolChoice());
        result.setMaxAttachedMessageCount(Math.max(1, selected.size()));
        result.addMessages(selected);
        if (source.getTemporaryMessages() != null) {
            for (Message message : source.getTemporaryMessages()) {
                result.addMessageTemporary(AgentMessageUtils.copyMessage(message));
            }
        }
        return result;
    }

public static AgentContextCompressor perMessageModel(
        ChatModel model, AgentContextModelCompressorOptions options) {
        if (model == null) throw new IllegalArgumentException("model must not be null");
        if (options == null) throw new IllegalArgumentException("options must not be null");
        return messages -> {
            StringBuilder input = new StringBuilder(options.getInstruction())
                .append(options.getPerMessageRequest());
            boolean hasCompressibleMessage = false;
            for (Message message : messages) {
                if (message instanceof AiMessage && ((AiMessage) message).hasToolCalls()) continue;
                if (message instanceof com.agentsflex.core.message.ToolMessage) continue;
                String formatted = format(options.getPerMessageFormatter(), message);
                if (message.getMessageId() == null || !formatted.contains(message.getMessageId())) {
                    throw new IllegalStateException(
                        "per-message compression formatter must include messageId");
                }
                input.append(formatted);
                hasCompressibleMessage = true;
            }
            if (!hasCompressibleMessage) {
                return copy(messages);
            }
            validateSize("per-message compression input", input.length(),
                options.getMaxInputCharacters());
            AiMessageResponse response = callModel(model, new SimplePrompt(input.toString()), options);
            if (response == null || response.isError() || response.getMessage() == null) {
                if (response != null && response.isError()) response.throwIfError();
                throw new IllegalStateException("per-message summary model returned no message");
            }
            String content = response.getMessage().getContent();
            if (content == null || content.trim().isEmpty()) {
                throw new IllegalStateException("per-message summary model returned empty content");
            }
            validateSize("per-message compression output", content.length(),
                options.getMaxOutputCharacters());
            content = content.trim();
            if (content.startsWith("```")) {
                int firstLine = content.indexOf('\n');
                int lastFence = content.lastIndexOf("```");
                if (firstLine > 0 && lastFence > firstLine) {
                    content = content.substring(firstLine + 1, lastFence).trim();
                }
            }
            JSONArray summaries;
            try {
                summaries = JSON.parseArray(content);
            } catch (RuntimeException e) {
                throw new IllegalStateException("per-message summary model must return a JSON array", e);
            }
            java.util.Map<String, String> byId = new java.util.HashMap<>();
            for (Object value : summaries) {
                if (!(value instanceof JSONObject)) {
                    throw new IllegalStateException(
                        "per-message summary model must return JSON objects");
                }
                JSONObject item = (JSONObject) value;
                String id = item.getString("messageId");
                String summary = item.getString("summary");
                if (id != null && summary != null) byId.put(id, summary);
            }
            List<Message> result = new ArrayList<>();
            for (Message original : messages) {
                String summary = byId.get(original.getMessageId());
                if (summary == null || (original instanceof AiMessage && ((AiMessage) original).hasToolCalls())
                    || original instanceof com.agentsflex.core.message.ToolMessage) {
                    result.add(CompressionMessageUtils.copyMessage(original));
                } else if (original instanceof UserMessage) {
                    UserMessage copy = ((UserMessage) original).copy();
                    copy.setContent(summary);
                    result.add(copy);
                } else if (original instanceof AiMessage) {
                    AiMessage copy = ((AiMessage) original).copy();
                    copy.setContent(summary);
                    copy.setToolCalls(null);
                    result.add(copy);
                } else {
                    result.add(CompressionMessageUtils.copyMessage(original));
                }
            }
            return result;
        };
    }

@ToolDef(
        name = "calculate",
        description = "" +
            "=== ⚠️ MANDATORY: ALL Math Calculations MUST Use This Tool ===\n\n" +

            "You are STRICTLY PROHIBITED from performing ANY mathematical calculations yourself.\n" +
            "This tool is the ONLY way to perform calculations. Violation is not allowed.\n\n" +

            "=== When to Use (MANDATORY) ===\n" +
            "- Addition, subtraction, multiplication, division\n" +
            "- Percentage calculations (e.g., 'what is 15% of 200?')\n" +
            "- Ratio calculations (e.g., 'what percentage is 30 out of 150?')\n" +
            "- Any arithmetic operations\n" +
            "- Converting between units that require math\n" +
            "- Comparing values that require subtraction\n\n" +

            "=== Supported Operations ===\n" +
            "- add: a + b\n" +
            "- subtract: a - b\n" +
            "- multiply: a * b\n" +
            "- divide: a / b\n" +
            "- percentage: calculate a% of b (e.g., 15% of 200)\n" +
            "- percentage_of: what percentage is a of b (e.g., 30 is what % of 150)\n" +
            "- percentage_change: percentage change from a to b\n" +
            "- power: a ^ b\n" +
            "- sqrt: square root of a\n" +
            "- abs: absolute value of a\n" +
            "- round: round a to b decimal places\n\n" +

            "=== Examples ===\n" +
            "- 'Calculate 123 + 456' → operation='add', a=123, b=456\n" +
            "- 'What is 15% of 200?' → operation='percentage', a=15, b=200\n" +
            "- '30 is what percentage of 150?' → operation='percentage_of', a=30, b=150\n" +
            "- 'Round 3.14159 to 2 decimal places' → operation='round', a=3.14159, b=2\n"
    )
    public String calculate(
        @ToolParam(name = "operation", description = "The operation to perform. Must be one of: " +
            "add, subtract, multiply, divide, percentage, percentage_of, percentage_change, power, sqrt, abs, round.\n" +
            "- add: a + b\n" +
            "- subtract: a - b\n" +
            "- multiply: a * b\n" +
            "- divide: a / b\n" +
            "- percentage: calculate a% of b (e.g., a=15, b=200 → 15% of 200 = 30)\n" +
            "- percentage_of: what percentage a is of b (e.g., a=30, b=150 → 30 is 20% of 150)\n" +
            "- percentage_change: percentage change from a to b (e.g., a=100, b=120 → 20% increase)\n" +
            "- power: a raised to the power of b\n" +
            "- sqrt: square root of a (b is ignored)\n" +
            "- abs: absolute value of a (b is ignored)\n" +
            "- round: round a to b decimal places\n") String operation,
        @ToolParam(name = "a", description = "First operand. For percentage operations, this is the percentage value or the part value.") Double a,
        @ToolParam(name = "b", description = "Second operand. For percentage operations, this is the base value. For sqrt/abs, this is ignored. For round, this is decimal places.") Double b
    ) {
        if (operation == null || operation.trim().isEmpty()) {
            return error("Operation cannot be empty");
        }
        if (a == null) {
            return error("Parameter 'a' cannot be null");
        }

        try {
            BigDecimal result;
            String expression;

            switch (operation.toLowerCase().trim()) {
                case "add":
                    if (b == null) return error("Parameter 'b' is required for add operation");
                    result = BigDecimal.valueOf(a).add(BigDecimal.valueOf(b));
                    expression = a + " + " + b + " = " + result;
                    break;

                case "subtract":
                    if (b == null) return error("Parameter 'b' is required for subtract operation");
                    result = BigDecimal.valueOf(a).subtract(BigDecimal.valueOf(b));
                    expression = a + " - " + b + " = " + result;
                    break;

                case "multiply":
                    if (b == null) return error("Parameter 'b' is required for multiply operation");
                    result = BigDecimal.valueOf(a).multiply(BigDecimal.valueOf(b));
                    expression = a + " × " + b + " = " + result;
                    break;

                case "divide":
                    if (b == null) return error("Parameter 'b' is required for divide operation");
                    if (b == 0) return error("Division by zero is not allowed");
                    result = BigDecimal.valueOf(a).divide(BigDecimal.valueOf(b), 10, RoundingMode.HALF_UP);
                    expression = a + " ÷ " + b + " = " + formatResult(result);
                    break;

                case "percentage":
                    // Calculate a% of b
                    if (b == null) return error("Parameter 'b' is required for percentage operation");
                    result = BigDecimal.valueOf(a)
                        .divide(BigDecimal.valueOf(100), 10, RoundingMode.HALF_UP)
                        .multiply(BigDecimal.valueOf(b));
                    expression = a + "% of " + b + " = " + formatResult(result);
                    break;

                case "percentage_of":
                    // Calculate what percentage a is of b
                    if (b == null) return error("Parameter 'b' is required for percentage_of operation");
                    if (b == 0) return error("Base value cannot be zero");
                    result = BigDecimal.valueOf(a)
                        .divide(BigDecimal.valueOf(b), 10, RoundingMode.HALF_UP)
                        .multiply(BigDecimal.valueOf(100));
                    expression = a + " is " + formatResult(result) + "% of " + b;
                    break;

                case "percentage_change":
                    // Calculate percentage change from a to b
                    if (b == null) return error("Parameter 'b' is required for percentage_change operation");
                    if (a == 0) return error("Original value cannot be zero");
                    result = BigDecimal.valueOf(b - a)
                        .divide(BigDecimal.valueOf(a), 10, RoundingMode.HALF_UP)
                        .multiply(BigDecimal.valueOf(100));
                    String direction = result.compareTo(BigDecimal.ZERO) >= 0 ? "increase" : "decrease";
                    expression = "Change from " + a + " to " + b + " = " + formatResult(result.abs()) + "% " + direction;
                    break;

                case "power":
                    if (b == null) return error("Parameter 'b' is required for power operation");
                    result = BigDecimal.valueOf(Math.pow(a, b));
                    expression = a + " ^ " + b + " = " + formatResult(result);
                    break;

                case "sqrt":
                    if (a < 0) return error("Cannot calculate square root of negative number");
                    result = BigDecimal.valueOf(Math.sqrt(a));
                    expression = "√" + a + " = " + formatResult(result);
                    break;

                case "abs":
                    result = BigDecimal.valueOf(Math.abs(a));
                    expression = "|" + a + "| = " + result;
                    break;

                case "round":
                    if (b == null) b = 0.0;
                    int decimals = b.intValue();
                    if (decimals < 0) decimals = 0;
                    result = BigDecimal.valueOf(a).setScale(decimals, RoundingMode.HALF_UP);
                    expression = "Round " + a + " to " + decimals + " decimal places = " + result;
                    break;

                default:
                    return error("Unknown operation: '" + operation + "'. Supported: add, subtract, multiply, divide, percentage, percentage_of, percentage_change, power, sqrt, abs, round");
            }

            return success(expression);

        } catch (Exception e) {
            return error("Calculation error: " + e.getMessage());
        }
    }

AgentStepResult executePendingTools(AgentTurn turn, AiMessageResponse response) {
        // 工具及其拦截器可能读取 ChatContext；恢复路径没有原响应时需要从 Turn 补建上下文。
        ChatContext chatContext = chatContextForToolExecution(turn, response);
        // 并行处理器用 null 表示当前批次不适合并行，调用方继续使用语义更完整的顺序路径。
        if (turn.getExecutionPolicy().getToolExecutionMode() == AgentToolExecutionMode.PARALLEL
            && turn.getPendingToolCalls().size() > 1) {
            AgentStepResult parallel = executePendingToolsInParallel(turn, response, chatContext);
            if (parallel != null) return parallel;
        }
        List<ToolMessage> results = new ArrayList<>();
        while (!turn.getPendingToolCalls().isEmpty()) {
            // 每个工具副作用前重新检查取消和通用预算，避免一个长批次越过控制面更新。
            if (turn.isCancellationRequested()) {
                return runner.cancelTurn(turn);
            }
            String budgetReason = runner.budgetExceededReason(turn, false);
            if (budgetReason != null) {
                return runner.budgetExceeded(turn, budgetReason);
            }

            // 顺序路径始终处理队首；只有结果成功持久化后才会移除该 pending 调用。
            ToolCall call = turn.getPendingToolCalls().get(0);
            Tool tool = resolveTool(turn, call);
            if (tool == null) {
                // Snapshot 只保存工具名称；恢复后缺少同版本工具属于不可重试的配置错误。
                return runner.handleFailure(turn, response,
                    new AgentRunner.AgentToolNotFoundException(call.getName()),
                    AgentTurnExecutionPoint.PROCESS_TOOLS);
            }

            if (AgentUserInputTool.isUserInputTool(tool)) {
                // 内置输入工具不执行业务函数，而是把 Schema 固化到 Suspension 后等待用户提交。
                try {
                    AgentFormDefinition form = AgentUserInputTool.resolveForm(tool, call);
                    Object title = form.getSchema().get("title");
                    String message = title == null ? form.getFormKey() : String.valueOf(title);
                    AgentSuspension suspension = AgentSuspension.userInput(
                        callKey(call), message, form.getFormKey(), form.getSchema(),
                        AgentUserInputTool.NAME, null,
                        turn.getExecutionPolicy().getUserInputTimeoutMillis());
                    runner.suspend(turn, suspension);
                    return AgentStepResult.of(response, results, null);
                } catch (RuntimeException error) {
                    return runner.handleFailure(turn, response, error,
                        AgentTurnExecutionPoint.PROCESS_TOOLS);
                }
            }

            // 内置控制工具不计入业务工具预算，因此 maxToolCalls 只在确定执行真实工具后检查。
            budgetReason = runner.budgetExceededReason(turn, true);
            if (budgetReason != null) {
                return runner.budgetExceeded(turn, budgetReason);
            }

            // 中央策略是第一层授权边界；已恢复的审批记录优先于再次调用动态策略。
            ToolApprovalDecision decision;
            try {
                ToolApprovalRecord policyRecord = turn.getToolApprovalRecord(
                    callKey(call), ToolApprovalStage.POLICY);
                decision = policyRecord == null
                    ? turn.getAgent().getToolApprovalPolicy().decide(turn, call, tool)
                    : decisionFromRecord(policyRecord);
            } catch (RuntimeException policyError) {
                return runner.handleFailure(turn, response, policyError,
                    AgentTurnExecutionPoint.PROCESS_TOOLS);
            }
            if (decision == null) {
                return runner.handleFailure(turn, response,
                    new IllegalStateException("ToolApprovalPolicy returned null"),
                    AgentTurnExecutionPoint.PROCESS_TOOLS);
            }
            if (decision.getOutcome() == ToolApprovalDecision.Outcome.REQUIRE_APPROVAL) {
                // 保存原 ToolCall 和 PROCESS_TOOLS 恢复点，批准后无需让模型重新生成参数。
                AgentSuspension suspension = AgentSuspension.toolApproval(
                    callKey(call), call.getName(), decision, ToolApprovalStage.POLICY,
                    turn.getExecutionPolicy().getApprovalTimeoutMillis());
                runner.suspend(turn, suspension);
                eventPublisher.notifyToolApprovalRequested(turn, call, decision);
                return AgentStepResult.of(response, results, null);
            }
            if (decision.getOutcome() == ToolApprovalDecision.Outcome.DENY) {
                // 拒绝是模型可消费的正常工具结果，不进入异常重试流程。
                ToolMessage rejected = buildToolRejectedMessage(turn, call, decision);
                appendToolResult(turn, rejected);
                results.add(rejected);
                continue;
            }

            // Tool 主动审批的拒绝记录优先于重新执行，避免再次进入其只读预检代码。
            ToolApprovalRecord toolRecord = turn.getToolApprovalRecord(
                callKey(call), ToolApprovalStage.TOOL);
            if (toolRecord != null && !toolRecord.isApproved()) {
                ToolMessage rejected = buildToolRejectedMessage(
                    turn, call, decisionFromRecord(toolRecord));
                appendToolResult(turn, rejected);
                results.add(rejected);
                continue;
            }

            if (tool.getExecutionTarget() == ToolExecutionTarget.EXTERNAL) {
                // 外部工具只登记请求并挂起；浏览器或其他执行器稍后通过 ResumeCommand 回传结果。
                turn.incrementToolCallCount();
                AgentSuspension suspension = AgentSuspension.externalTool(
                    callKey(call), call.getName(), call.getArguments(), tool.getMetadata(),
                    turn.getExecutionPolicy().getExternalToolTimeoutMillis());
                runner.suspend(turn, suspension);
                eventPublisher.notifyExternalToolRequested(turn, call, tool);
                return AgentStepResult.of(response, results, null);
            }

            eventPublisher.notifyToolStart(turn, call);
            ToolMessage completedResult;
            try {
                // 调用次数在进入业务工具前增加；控制流异常会在 catch 分支回滚。
                turn.incrementToolCallCount();
                completedResult = executeTool(
                    turn, tool, call, runnerOptions.getToolExecutor(), chatContext);
            } catch (AgentApprovalRequiredException request) {
                // Tool 主动审批发生在副作用前；记录请求指纹以阻止已批准请求形成审批循环。
                turn.rollbackToolCallCount();
                ToolApprovalRecord previous = turn.getToolApprovalRecord(
                    callKey(call), ToolApprovalStage.TOOL,
                    request.getDecision().getRequestFingerprint());
                if (isSameApprovedRequest(previous, request.getDecision())) {
                    IllegalArgumentException error = repeatedToolApproval(call, request);
                    eventPublisher.notifyToolError(turn, call, error);
                    return runner.handleFailure(turn, response, error,
                        AgentTurnExecutionPoint.PROCESS_TOOLS);
                }
                ToolApprovalDecision toolDecision = toolApprovalDecision(request.getDecision());
                AgentSuspension suspension = AgentSuspension.toolApproval(
                    callKey(call), call.getName(), toolDecision, ToolApprovalStage.TOOL,
                    turn.getExecutionPolicy().getApprovalTimeoutMillis());
                runner.suspend(turn, suspension);
                eventPublisher.notifyToolApprovalRequested(turn, call, toolDecision);
                return AgentStepResult.of(response, results, null);
            } catch (AgentFormRequiredException request) {
                // 表单请求同样属于控制流而非失败，本次未完成的工具调用不消耗调用预算。
                turn.rollbackToolCallCount();
                AgentFormDefinition form = request.getForm();
                AgentSuspension suspension = AgentSuspension.userInput(
                    callKey(call), request.getMessage(), form.getFormKey(), form.getSchema(),
                    call.getName(), AgentRunner.TOOL_INPUT_TARGET,
                    turn.getExecutionPolicy().getUserInputTimeoutMillis());
                runner.suspend(turn, suspension);
                eventPublisher.notifyToolInputRequested(turn, call, form);
                return AgentStepResult.of(response, results, null);
            } catch (RuntimeException error) {
                runner.refreshCancellation(turn);
                if (turn.isCancellationRequested()) {
                    // 停止导致的资源关闭异常不能被当成普通 ToolError 回传给模型。
                    return runner.cancelTurn(turn);
                }
                // Middleware/Interceptor 可能包装控制流异常，必须沿 cause 链恢复原始语义。
                AgentApprovalRequiredException approvalRequest = findCause(
                    error, AgentApprovalRequiredException.class);
                if (approvalRequest != null) {
                    turn.rollbackToolCallCount();
                    ToolApprovalRecord previous = turn.getToolApprovalRecord(
                        callKey(call), ToolApprovalStage.TOOL,
                        approvalRequest.getDecision().getRequestFingerprint());
                    if (isSameApprovedRequest(previous, approvalRequest.getDecision())) {
                        IllegalArgumentException repeated = repeatedToolApproval(call, error);
                        eventPublisher.notifyToolError(turn, call, repeated);
                        return runner.handleFailure(turn, response, repeated,
                            AgentTurnExecutionPoint.PROCESS_TOOLS);
                    }
                    ToolApprovalDecision toolDecision = toolApprovalDecision(
                        approvalRequest.getDecision());
                    AgentSuspension suspension = AgentSuspension.toolApproval(
                        callKey(call), call.getName(), toolDecision, ToolApprovalStage.TOOL,
                        turn.getExecutionPolicy().getApprovalTimeoutMillis());
                    runner.suspend(turn, suspension);
                    eventPublisher.notifyToolApprovalRequested(turn, call, toolDecision);
                    return AgentStepResult.of(response, results, null);
                }
                AgentFormRequiredException formRequest = findCause(
                    error, AgentFormRequiredException.class);
                if (formRequest != null) {
                    turn.rollbackToolCallCount();
                    AgentFormDefinition form = formRequest.getForm();
                    AgentSuspension suspension = AgentSuspension.userInput(
                        callKey(call), formRequest.getMessage(), form.getFormKey(),
                        form.getSchema(), call.getName(), AgentRunner.TOOL_INPUT_TARGET,
                        turn.getExecutionPolicy().getUserInputTimeoutMillis());
                    runner.suspend(turn, suspension);
                    eventPublisher.notifyToolInputRequested(turn, call, form);
                    return AgentStepResult.of(response, results, null);
                }
                eventPublisher.notifyToolError(turn, call, error);
                if (turn.getExecutionPolicy().getToolErrorStrategy()
                    == ToolErrorStrategy.RETURN_ERROR_TO_MODEL) {
                    // 配置允许时把普通异常转换为结构化 ToolMessage，让模型选择解释或替代方案。
                    completedResult = buildToolErrorMessage(turn, call, error);
                } else {
                    return runner.handleFailure(turn, response, error,
                        AgentTurnExecutionPoint.PROCESS_TOOLS);
                }
            }
            // Snapshot 保存异常必须直接向上传播，不能被误判为业务工具失败。
            appendToolResult(turn, completedResult);
            results.add(completedResult);
            eventPublisher.notifyToolEnd(turn, call);
            runner.refreshCancellation(turn);
        }

        // 本轮全部工具协议已经闭合，下一 Step 才能再次调用模型读取结果。
        turn.moveTo(AgentTurnExecutionPoint.INVOKE_MODEL);
        runner.saveSnapshot(turn);
        return AgentStepResult.of(response, results, null);
    }

